    cin.tie(0);cout.tie(0); 
    cin >> n >> weight ; 
    for ( int i = 1 ; i <= n ; i ++ ) cin >> h [i] ; 
    for ( int i = 1 ; i <= n ; i ++ ) cin >> w [i] ; 
    memset(dp,-0x3f,sizeof dp) ; 
    dp [0] = 0 ; 
    for ( int i = 1 ; i <= n ; i ++ ) 
    {
        for ( int j = weight ; j >= h [i] ; j -- ) chkmax (dp[j],dp[j-h[i]]+w[i]) ; 
    }
    cout << *max_element(dp,dp+weight+1) ; 
    return 0;
}
